mapper.select:
SELECT C.* FROM SMT_AUTH_SOURCE_RESOURCE C JOIN SMT_AUTH_RESOURCE_COORD R ON R.ID=C.RESOURCE_COORD_ID
  WHERE C.SOURCE_COORD_ID=#{sourceId} AND C.SOURCE_GENERATION=#{generation} AND C.BINDING_REVISION=0
    AND R.PARK_ID=#{resource.parkId} AND R.SUBJECT_TYPE=#{resource.subjectType} AND R.SUBJECT_ID=#{resource.subjectId}
    AND R.ACCESS_TYPE=#{resource.accessType} AND R.DEVICE_ID=#{resource.deviceId} AND R.RESOURCE_TYPE=#{resource.resourceType}
    AND R.RESOURCE_ID=#{resource.resourceId} AND R.SERVICE_TYPE=#{resource.serviceType} AND R.CREDENTIAL_CHANNEL=#{resource.credentialChannel}

SELECT * FROM (SELECT * FROM SMT_AUTH_SOURCE_RESOURCE WHERE SOURCE_COORD_ID=#{sourceId} AND SOURCE_GENERATION=#{generation}
  AND RESOURCE_COORD_ID=#{resourceId} AND TARGET_ID=#{targetId} AND REQUEST_ID=#{requestId} AND BINDING_REVISION >= 0
  ORDER BY BINDING_REVISION) WHERE ROWNUM=1

SELECT * FROM (SELECT DISTINCT TARGET_ID FROM SMT_AUTH_SOURCE_RESOURCE WHERE SOURCE_COORD_ID=#{sourceId}
  AND SOURCE_GENERATION=#{generation} AND BINDING_REVISION >= 0 AND TARGET_ID IS NOT NULL
  AND TARGET_ID > #{after} ORDER BY TARGET_ID) WHERE ROWNUM <= #{limit}
